from queue import Full, Queue


def accepted(cap: int, xs: list[int]) -> int:
    """Create a bounded queue with capacity `cap` and try to put each item in `xs`

    without blocking. Return the number of items successfully accepted before the
    queue became full.
    """
    if cap <= 0:
        return 0
    q: Queue[int] = Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
            count += 1
        except Full:
            break
    return count


def test_accepted_empty() -> None:
    assert accepted(3, []) == 0


def test_accepted_fewer_than_capacity() -> None:
    assert accepted(5, [1, 2, 3]) == 3


def test_accepted_exact_capacity() -> None:
    assert accepted(3, [10, 20, 30]) == 3


def test_accepted_exceeds_capacity() -> None:
    assert accepted(2, [1, 2, 3, 4]) == 2


def test_accepted_zero_capacity() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_accepted_capacity_one() -> None:
    assert accepted(1, [42]) == 1
    assert accepted(1, [42, 99]) == 1

